<script setup lang="ts">
import { onBeforeUnmount, ref } from 'vue'
import { tutorApi, tutorToolLabel, benchmarkValue, type TutorBenchmarkReport } from '../lib/tutor'
import { downloadJSON, percent } from '../lib/documents'
import { message, sessionFrozen } from '../lib/state'
import Icon from './Icon.vue'
const report=ref<TutorBenchmarkReport>(),busy=ref(false),error=ref('')
let disposed=false
const operations={rule:'规则动作',action:'受控工具动作',answer:'固定学习者回答',probe:'工具边界检查','answer-probe':'作答边界检查'}
const outcomes={applied:'已执行',rejected:'已拒绝',error:'执行错误'}
async function run(){if(busy.value||sessionFrozen.value)return;busy.value=true;error.value='';try{const data=await tutorApi.benchmark();if(!disposed&&!sessionFrozen.value)report.value=data.report}catch(e){if(!disposed&&!sessionFrozen.value)error.value=message(e)}finally{if(!disposed)busy.value=false}}
onBeforeUnmount(()=>disposed=true)
</script>
<template><section class="surface tutor-benchmark"><div class="section-head"><div><span class="topic-label">离线策略与约束回归 · 不调用模型</span><h2>教学行为基准</h2></div><button class="button" :disabled="busy" @click="run"><Icon name="check"/>{{busy?'正在验证行为…':'运行教学行为基准'}}</button></div><p class="muted">用固定原创场景检查诊断、追问、证据边界与停止约束。受控策略使用预先编写的工具动作，非模型调用；通过率不代表真实模型质量或学习效果。</p><p v-if="error" class="error" role="alert">{{error}}</p><template v-if="report"><div class="benchmark-meta"><span>{{report.caseCount}} 个原创场景 · {{report.version}}</span><button class="text-button" @click="downloadJSON(report,'tutor-benchmark.json')"><Icon name="download"/>导出实际结果 JSON</button></div><ul class="report-limits"><li v-for="limit in report.limitations" :key="limit">{{limit}}</li></ul><div class="benchmark-strategies tutor-benchmark-strategies"><article v-for="strategy in report.strategies" :key="strategy.name"><h3>{{strategy.name==='rule'?'规则教练':'受控工具策略 · 离线'}}</h3><div class="quality-summary"><span>检查通过 {{strategy.summary.passedChecks}} / {{strategy.summary.checks}}</span><span>{{percent(strategy.summary.passRate)}}</span></div><p class="small muted">场景通过 {{strategy.summary.passedCases}} / {{strategy.summary.cases}} · 执行错误 {{strategy.summary.errorCases}}，失败保留在总数中</p><details v-for="item in strategy.cases" :key="item.id"><summary>{{item.title}} · {{item.passed?'通过':'未通过'}}</summary><p>{{item.goal}}</p><p v-if="item.error" class="error">{{item.error}}</p><ul class="tutor-benchmark-checks"><li v-for="check in item.checks" :key="check.code"><strong><Icon :name="check.passed?'check':'warning'"/>{{check.message}}</strong><p>预期：{{benchmarkValue(check.expected)}}<br/>观察：{{benchmarkValue(check.observed)}}</p></li></ul><details class="tutor-benchmark-trace"><summary>查看 {{item.actualTrace.length}} 步实际轨迹</summary><article v-for="step in item.actualTrace" :key="step.step"><strong>{{step.step}} · {{step.tool?tutorToolLabel(step.tool):operations[step.operation]}}</strong><p>{{outcomes[step.outcome]}}<span v-if="step.outcome==='rejected'"> · {{step.stateUnchanged?'拒绝后状态保持不变':'拒绝后状态发生变化'}}</span></p><p v-if="step.error">{{step.error}}</p><p v-for="(trace,i) in step.engineTrace" :key="i">{{trace.message}}</p><details><summary>固定场景输入</summary><pre>{{JSON.stringify(step.input,null,2)}}</pre></details></article></details></details></article></div><details class="tutor-benchmark-provenance"><summary>数据集与可复现信息</summary><p>{{report.datasetId}} · {{report.datasetVersion}}</p><p class="hash-line">SHA256 {{report.datasetHash}}</p><p>{{report.createdAt}}</p></details></template></section></template>
